": Kopie mit Prüfung (Dokument für Dokument) und Umschaltung. Beim Umschalten geht die App kurz in den Wartungsmodus, die Kopie wird ein letztes Mal erneuert und nur bei vollständiger Übereinstimmung wird umgeschaltet. Vorher eine aktuelle Sicherung erstellen. Zurückschalten ist jederzeit möglich (mit Rückkopie).": ": نسخ مع تحقق (مستندًا تلو الآخر) ثم تحويل. عند التحويل يدخل التطبيق لفترة قصيرة في وضع الصيانة، وتُحدَّث النسخة مرة أخيرة، ولا يتم التحويل إلا عند التطابق الكامل. أنشئ قبل ذلك نسخة احتياطية حديثة. العودة ممكنة في أي وقت (مع نسخ عكسي).",
