"An diesen Tagen findet kein reguläres Training statt; Sondertrainings gelten zusätzlich (auch in den Ferien). Bereits erfasste Anwesenheiten bleiben erhalten. Trainingstage werden ab 2026 bis Ende": "لا يُقام تدريب منتظم في هذه الأيام؛ وتُضاف التدريبات الخاصة (حتى في العطل). يتم الاحتفاظ بالحضور المسجل مسبقًا. تُنشأ أيام التدريب من 2026 حتى نهاية",
"Noch nicht gespeichert – angezeigt wird die bisherige Vorbelegung. Bitte die Ferien der kommenden Zeit ergänzen und speichern.": "لم يُحفظ بعد – تُعرض القيم الافتراضية السابقة. يُرجى إضافة العطل القادمة والحفظ.",
"📅 Trainingstage je Gruppe": "📅 أيام التدريب لكل مجموعة",
"An diesen Wochentagen entstehen die Trainingstage (Anwesenheit, Teilnahme, Rangliste). „Übrige Gruppen“ gilt für alle nicht eigens aufgeführten Gruppen. Trainer wählen ihre Tage im Profil.": "في أيام الأسبوع هذه تُنشأ أيام التدريب (الحضور، المشاركة، الترتيب). «المجموعات الأخرى» تنطبق على كل المجموعات غير المذكورة منفصلة. يختار المدربون أيامهم في الملف الشخصي.",
