"Artikel, Preise und Größen für den Reiter „Bestellung“. Die Reihenfolge hier ist die Anzeige-Reihenfolge. Druck-Artikel haben keine Größe; ihre Menge folgt automatisch den gekoppelten Hauptartikeln. Nicht mehr angebotene Artikel bitte": "الأصناف والأسعار والمقاسات لعلامة التبويب «الطلب». الترتيب هنا هو ترتيب العرض. أصناف الطباعة بلا مقاس؛ وتتبع كميتها تلقائيًا الأصناف الرئيسية المرتبطة. الأصناف التي لم تعد معروضة يُرجى",
