"⚠️ Doppelte Profile ·": "⚠️ ملفات مكررة ·",
"Für die folgenden Personen gibt es mehrere Profile mit derselben E-Mail-Adresse und demselben Namen. Das führt zu doppelten Einträgen in den Übersichten. Behalte das verknüpfte Profil (mit Login) und entferne die Dublette. Die Bestellung wird dabei, falls nötig, auf das behaltene Profil übernommen.": "للأشخاص التالين توجد عدة ملفات بنفس البريد ونفس الاسم. يؤدي ذلك إلى إدخالات مكررة في النظرات العامة. احتفظ بالملف المرتبط (مع حساب) واحذف المكرر. عند الحاجة يُنقل الطلب إلى الملف المحتفظ به.",
