"Spieler deiner Mannschaft{0}.": "لاعبو فريقك{0}.",
"✏️ Bestellung für eine Person eingeben/bearbeiten": "✏️ إدخال/تعديل طلب لشخص",
"Person wählen…": "اختر شخصًا…",
"Dir ist noch keine Mannschaft als Mannschaftsführer zugeordnet. Bitte in der Verwaltung im Profil das Feld „Mannschaftsführer-Team“ setzen, dann erscheinen hier die Spieler deiner Mannschaft.": "لم يُعيَّن لك فريق كقائد بعد. يُرجى تعيين الحقل «فريق القائد» في الملف الشخصي ضمن الإدارة، وعندها سيظهر لاعبو فريقك هنا.",
"Für die Mannschaft „{0}“ sind in der aktuellen Aufstellung keine Spieler hinterlegt.": "لا يوجد لاعبون مسجلون في التشكيلة الحالية لفريق «{0}».",
"Keine passenden Personen vorhanden.": "لا يوجد أشخاص مطابقون.",
"⬜ leer": "⬜ فارغ",
"✔ vorhanden (grau)": "✔ متوفر (رمادي)",
"✔ übergeben (grün)": "✔ تم التسليم (أخضر)",
"keine Bestellung": "لا طلب",
"übergeben (grün) – Klick zum Leeren": "تم التسليم (أخضر) – انقر للإفراغ",
"vorhanden (grau) – Klick für übergeben": "متوفر (رمادي) – انقر لـ «تم التسليم»",
"leer – Klick für vorhanden": "فارغ – انقر لـ «متوفر»",
"Geldeingang bestätigen": "تأكيد استلام المبلغ",
"Gesamtsumme": "المجموع الكلي",
"„bestellt\" und „bezahlt\" werden gesetzt, sobald die Person verbindlich bestellt. „Geldeingang\" hakst nur du ab, wenn das Geld auf dem Vereinskonto ist.": "يُعيَّن «مطلوب» و«مدفوع» بمجرد أن يقدّم الشخص طلبه نهائيًا. أما «استلام المبلغ» فتؤشر عليه أنت فقط عندما يصل المال إلى حساب النادي.",
"Auf iPhone/iPad zuerst über „Teilen → Zum Home-Bildschirm“ hinzufügen, dann hier aktivieren.": "على iPhone/iPad أضف التطبيق أولًا عبر «مشاركة ← إضافة إلى الشاشة الرئيسية»، ثم فعّل هنا.",
"Aktivieren nicht möglich.": "التفعيل غير ممكن.",
"Für Benachrichtigungen die App über „Teilen → Zum Home-Bildschirm“ hinzufügen.": "لتلقي الإشعارات أضف التطبيق عبر «مشاركة ← إضافة إلى الشاشة الرئيسية».",
"Aktiviere Benachrichtigungen, um keine Termine, Spiele und Geburtstage zu verpassen.": "فعّل الإشعارات حتى لا تفوتك المواعيد والمباريات وأعياد الميلاد.",
"Aktivieren": "تفعيل",
"Ausblenden": "إخفاء",
"Benachrichtigungen aktiviert": "تم تفعيل الإشعارات",
"Benachrichtigungen deaktiviert": "تم إيقاف الإشعارات",
"Das hat nicht geklappt.": "لم ينجح ذلك.",
"Keine persönlichen Daten gefunden.": "لم يُعثر على بيانات شخصية.",
"Datenschutzerklärung als PDF gespeichert": "تم حفظ سياسة الخصوصية بصيغة PDF",
"Die PDF konnte nicht erstellt werden. Bitte prüfe die Internetverbindung und versuche es erneut.": "تعذّر إنشاء ملف PDF. يُرجى التحقق من اتصال الإنترنت والمحاولة مجددًا.",
"🗂️ Meine Verwaltung": "🗂️ بياناتي",
"Deine beim Verein hinterlegten Daten. Ändern kannst du selbst nur Handynummer, T-Shirt- und Anzugs-Größe. Für alle anderen Änderungen wende dich bitte an den Admin.": "بياناتك المسجلة لدى النادي. يمكنك بنفسك تغيير رقم الجوال ومقاس القميص والبدلة فقط. لأي تغييرات أخرى يُرجى التواصل مع المشرف.",
"✏️ Selbst änderbar": "✏️ قابل للتعديل من قبلك",
"Handynummer": "رقم الجوال",
"Anzugs-Größe": "مقاس البدلة الرياضية",
"💾 Änderungen speichern": "💾 حفظ التغييرات",
"🔔 Benachrichtigungen": "🔔 الإشعارات",
"Dieser Browser unterstützt keine Benachrichtigungen. Tipp: Die Termine lassen sich über den Reiter „Kalender“ abonnieren – dann erinnert dich dein Kalender automatisch.": "هذا المتصفح لا يدعم الإشعارات. نصيحة: يمكنك الاشتراك في المواعيد عبر علامة التبويب «التقويم» – وعندها يذكّرك تقويمك تلقائيًا.",
"Einen Moment…": "لحظة…",
"Vor bevorstehenden Terminen erinnern": "التذكير قبل المواعيد القادمة",
"Du bekommst eine kurze Meldung auf dein Gerät, bevor ein Spiel, Training oder Vereinstermin ansteht. Du kannst das hier jederzeit wieder abschalten.": "تتلقى رسالة قصيرة على جهازك قبل مباراة أو تدريب أو موعد للنادي. يمكنك إيقاف ذلك هنا في أي وقت.",
" Auf iPhone und iPad funktioniert das nur, wenn die App über „Teilen → Zum Home-Bildschirm“ hinzugefügt wurde.": " على iPhone وiPad يعمل ذلك فقط إذا أُضيف التطبيق عبر «مشاركة ← إضافة إلى الشاشة الرئيسية».",
"🔒 Datenschutz": "🔒 الخصوصية",
"Bestätigt am": "تم التأكيد في",
"noch nicht bestätigt": "لم يُؤكَّد بعد",
"📄 Datenschutzerklärung (PDF)": "📄 سياسة الخصوصية (PDF)",
"Das ist die Erklärung, der bei der ersten Anmeldung zugestimmt wurde. Du kannst sie hier jederzeit als PDF-Datei öffnen, speichern oder ausdrucken.": "هذه هي السياسة التي تمت الموافقة عليها عند أول تسجيل دخول. يمكنك فتحها أو حفظها أو طباعتها هنا كملف PDF في أي وقت.",
"🔒 Nur durch Admin änderbar": "🔒 قابل للتعديل من المشرف فقط",
