"). Nur aktive Personen. Excel: „Vorname\", „Nachname\", „Geburtsdatum\" (TT.MM.JJJJ).": "). الأشخاص النشطون فقط. Excel: «Vorname» و«Nachname» و«Geburtsdatum» (يوم.شهر.سنة).",
