"Was hast du heute Neues gelernt?": "ما الجديد الذي تعلّمته اليوم؟",
"Bist du heute mit deiner Leistung zufrieden? Warum?": "هل أنت راضٍ عن أدائك اليوم؟ لماذا؟",
