"Wem möchtest du heute ein Lob aussprechen?": "من تودّ أن تمدحه اليوم؟",
"Welches Spiel hat dir am besten gefallen und warum?": "أي لعبة أعجبتك أكثر ولماذا؟",
"Was hat dich heute überrascht?": "ما الذي فاجأك اليوم؟",
"Was nimmst du dir für das nächste Training vor?": "ما الذي تخطط له للتدريب القادم؟",
