"Spielstaetten der Vereine (bis zu 3 je Verein). Die Liste ist aus dem Vereinsspielplan vorbelegt; Adressen koennen ergaenzt bzw. korrigiert und weitere Vereine angelegt werden. Aus diesen Angaben werden die Links zu Google Maps und Apple Karten gebildet – gesucht wird die Anschrift. Zeigt die Karte trotzdem nicht die richtige Halle, im Feld „Koordinaten“ die genaue Position hinterlegen: in Google Maps lange auf die Halle tippen und die angezeigten Zahlen kopieren, oder den Link der Halle einfügen. Mit „Test“ lässt sich das prüfen.": "صالات الأندية (حتى 3 لكل نادٍ). القائمة معبأة مسبقًا من جدول مباريات النادي؛ يمكن إكمال العناوين أو تصحيحها وإضافة أندية أخرى. من هذه البيانات تُنشأ الروابط إلى Google Maps وخرائط Apple – ويُبحث عن العنوان. إذا لم تُظهر الخريطة الصالة الصحيحة، أدخل الموقع الدقيق في حقل «الإحداثيات»: في Google Maps اضغط مطولًا على الصالة وانسخ الأرقام الظاهرة، أو الصق رابط الصالة. يمكنك التحقق بـ «اختبار».",
