"Aufgenommen werden die Spiele, für die {0} als Betreuer bestimmt {1}.": "تُدرج المباريات التي عُيِّن فيها {0} مرافقًا {1}.",
"Bitte mindestens eine Person auswählen, deren betreute Spiele aufgenommen werden sollen.": "يُرجى اختيار شخص واحد على الأقل لتُدرج مبارياته المرافَقة.",
