"Fahrt- & Auf-/Abbauzeit einrechnen": "احتساب وقت السفر والتجهيز/التفكيك",
"Der Kalendereintrag beginnt dann vor dem Spiel und endet danach — der eigentliche Spielbeginn steht in der Beschreibung.": "يبدأ إدخال التقويم عندها قبل المباراة وينتهي بعدها — موعد البداية الفعلي مذكور في الوصف.",
"Heimspiel:": "على أرضنا:",
