"Beispiel Nachwuchs 14:00 Uhr: Heim 13:00–16:00, Auswärts 13:00–16:00.": "مثال للناشئين الساعة 14:00: على أرضنا 13:00–16:00، خارج الأرض 13:00–16:00.",
"📲 Kalender abonnieren": "📲 الاشتراك في التقويم",
"(bleibt aktuell)": "(يبقى محدّثًا)",
"Einmal abonnieren — neue und geänderte Spiele erscheinen automatisch.": "اشترك مرة واحدة — تظهر المباريات الجديدة والمعدلة تلقائيًا.",
"Weg 1: mit der App „ICSx⁵“ (empfohlen)": "الطريقة 1: باستخدام تطبيق «ICSx⁵» (موصى به)",
"Die Google-Kalender-App selbst kann Web-Kalender leider nicht per Link abonnieren (sie fragt nur nach einer E-Mail-Adresse). Die kostenlose App „ICSx⁵“ übernimmt das zuverlässig und zeigt die Termine anschließend in deinem gewohnten Kalender an.": "لا يستطيع تطبيق تقويم Google نفسه للأسف الاشتراك في تقويمات الويب عبر رابط (يطلب فقط عنوان بريد). التطبيق المجاني «ICSx⁵» يقوم بذلك بشكل موثوق ثم يعرض المواعيد في تقويمك المعتاد.",
"Zuerst ICSx⁵ installieren, dann auf „2.“ tippen — der Kalender wird direkt übernommen. In ICSx⁵ lässt sich sogar einstellen, wie oft aktualisiert wird.": "ثبّت ICSx⁵ أولًا، ثم اضغط «2.» — يُضاف التقويم مباشرة. ويمكن في ICSx⁵ حتى ضبط عدد مرات التحديث.",
"Weg 2: über den Browser (ohne Zusatz-App)": "الطريقة 2: عبر المتصفح (بلا تطبيق إضافي)",
"Nur am Rechner (oder im Browser mit „Desktop-Ansicht“): auf calendar.google.com anmelden, links neben „Weitere Kalender“ auf „+“ → „Per URL“, dann den kopierten Link einfügen.": "على الحاسوب فقط (أو في المتصفح مع «عرض سطح المكتب»): سجّل الدخول في calendar.google.com، ثم بجانب «تقويمات أخرى» اضغط «+» ← «من عنوان URL»، ثم الصق الرابط المنسوخ.",
"Google Kalender (Browser) öffnen": "فتح تقويم Google (المتصفح)",
"+ In Kalender abonnieren": "+ الاشتراك في التقويم",
"✓ Link kopiert": "✓ تم نسخ الرابط",
"🔗 Abo-Link kopieren": "🔗 نسخ رابط الاشتراك",
"Der kopierte Link (beginnt mit https) lässt sich in ICSx⁵ oder am Rechner unter calendar.google.com → „Weitere Kalender → Per URL“ einfügen. Google aktualisiert Abos nur alle paar Stunden — ICSx⁵ kann häufiger aktualisieren.": "يمكن لصق الرابط المنسوخ (يبدأ بـ https) في ICSx⁵ أو على الحاسوب في calendar.google.com ← «تقويمات أخرى ← من عنوان URL». يحدّث Google الاشتراكات كل بضع ساعات فقط — ويمكن لـ ICSx⁵ التحديث أكثر.",
"Alternativ den Link kopieren und im Kalenderprogramm unter „Kalender abonnieren“ einfügen.": "بدلًا من ذلك انسخ الرابط والصقه في برنامج التقويم ضمن «الاشتراك في تقويم».",
