"📝 Digitaler Spielbericht folgt": "📝 تقرير المباراة الرقمي قريبًا",
"🏓 Willkommen": "🏓 مرحبًا",
"Aktuell kein anstehendes Spiel im Plan.": "لا توجد حاليًا مباراة قادمة في الجدول.",
"Deine nächste Betreuung": "مرافقتك القادمة",
