"Nachwuchs-Mannschaften sind alle, deren Name mit Jungen, Mädchen, Schüler, männliche oder weibliche Jugend beginnt; alle übrigen zählen zu den Erwachsenen. Hat eine Person mehrere Funktionen, zählt „Erwachsene\". Mit „(ehem.)\" gekennzeichnete Personen stehen nicht im Spielerstamm — meist Ehemalige aus der Zeit vor der App; sie gelten als passiv und erscheinen nur bei „Aktive + Inaktive\".": "فرق الناشئين هي كل الفرق التي يبدأ اسمها بـ Jungen أو Mädchen أو Schüler أو männliche أو weibliche Jugend؛ وكل البقية تُعد للبالغين. إذا كان للشخص عدة أدوار يُعتمد «بالغون». الأشخاص الموسومون بـ «(سابق)» غير موجودين في سجل اللاعبين — غالبًا أعضاء سابقون من قبل التطبيق؛ ويُعدّون غير نشطين ويظهرون فقط عند «النشطون + غير النشطين».",
