"Grundlage sind die Turniererfolge aller Personen – auch passiver und solcher, die nicht mehr im Spielerstamm stehen und beim Import der Datei „Turniererfolge“ gesondert übernommen wurden. Geteilte Plätze stehen in eigenen Zeilen. Beim Doppel werden die Partner über die Spalte „Partner“ der Turniererfolge oder über das Turnier zugeordnet; ohne diese Angabe stehen mehr als zwei Personen auf demselben Platz einzeln.": "الأساس هو نتائج البطولات لجميع الأشخاص – بمن فيهم غير النشطين ومن لم يعودوا في سجل اللاعبين وأُدرجوا بشكل منفصل عند استيراد ملف «نتائج البطولات». المراكز المشتركة في صفوف مستقلة. في الزوجي يُنسب الشريكان عبر عمود «الشريك» في نتائج البطولات أو عبر البطولة؛ ودون هذه المعلومة يُدرج أكثر من شخصين في المركز نفسه كلٌّ على حدة.",
"Turniererfolge": "نتائج البطولات",
