"{0} Turniererfolg(e) exportiert – allerdings ohne Rahmen und fixierte Kopfzeile, weil die Formatierungs-Bibliothek nicht geladen werden konnte ({1}).": "تم تصدير {0} نتيجة بطولة – لكن دون حدود وصف عناوين مثبت، لأنه تعذّر تحميل مكتبة التنسيق ({1}).",
