"{0} Person(en) aus dem Spielerstamm: bisherige Turniererfolge werden vollständig ersetzt. ": "{0} شخص من سجل اللاعبين: ستُستبدل نتائج البطولات السابقة بالكامل. ",
"Personen, die in der Datei nicht vorkommen, bleiben unverändert.\n\n": "الأشخاص غير الموجودين في الملف يبقون دون تغيير.\n\n",
"{0} Person(en) sind nicht im Spielerstamm (frühere Mitglieder). Ihre Erfolge werden ": "{0} شخص ليسوا في سجل اللاعبين (أعضاء سابقون). ستُ ",
"gesondert gespeichert und in den Statistiken mitgezählt.": "حفظ نتائجهم بشكل منفصل وتُحتسب في الإحصاءات.",
"Speichern der Personen außerhalb des Spielerstamms fehlgeschlagen: ": "فشل حفظ الأشخاص خارج سجل اللاعبين: ",
"{0} Turniererfolg(e) aus Reiter „{1}“ eingelesen.": "قُرئت {0} نتيجة بطولة من علامة التبويب «{1}».",
"{0} Person(en) im Spielerstamm aktualisiert{1}.": "تم تحديث {0} شخص في سجل اللاعبين{1}.",
", {0} fehlgeschlagen": "، فشل {0}",
"{0} Person(en) außerhalb des Spielerstamms gespeichert.": "تم حفظ {0} شخص خارج سجل اللاعبين.",
"Turniererfolge importiert": "تم استيراد نتائج البطولات",
"{0}: Fehler beim Lesen ({1}).": "{0}: خطأ في القراءة ({1}).",
"Alle Turniererfolge aller Personen als Excel-Datei – je Zeile ein Erfolg, mit genau den Feldern aus der Verwaltung: Typ, Turniername, Platz, Disziplin, Konkurrenz, Partner, Datum und Jahr. Auch Personen außerhalb des Spielerstamms sind enthalten (ohne Spieler-ID). Enthalten sind nur Erfolge aus Turnieren im Status „Abgeschlossen“ sowie manuell erfasste Erfolge. Erfolge aus inzwischen gelöschten Turnieren bleiben außen vor. Die Kopfzeile ist fixiert und über alle Spalten filterbar, alle Felder haben einen Rahmen. Die Spalten Spieler-ID, Vorname und Nachname ordnen jede Zeile ihrer Person zu; „Herkunft“ kennzeichnet Erfolge, die beim Abschluss eines Vereinsturniers automatisch übertragen wurden – bitte unverändert lassen. In „Partner“ steht beim Doppel der Partner als „Vorname Nachname“; die Spalte kann nachgetragen und die Datei wieder eingelesen werden. Beim Doppel reicht der Eintrag bei einem der beiden Partner. Dateien ohne diese Spalte lassen sich weiterhin einlesen.": "كل نتائج البطولات لجميع الأشخاص كملف Excel – نتيجة واحدة في كل صف، بالحقول نفسها تمامًا كما في الإدارة: النوع، اسم البطولة، المركز، الفئة، المسابقة، الشريك، التاريخ والسنة. يشمل أيضًا الأشخاص خارج سجل اللاعبين (دون معرّف لاعب). تُدرج فقط نتائج البطولات بحالة «مكتملة» والنتائج المدخلة يدويًا. تُستبعد نتائج البطولات المحذوفة منذ ذلك الحين. صف العناوين مثبت وقابل للتصفية في كل الأعمدة، ولكل الخلايا حدود. تنسب أعمدة معرّف اللاعب والاسم الأول واسم العائلة كل صف إلى صاحبه؛ ويشير «المصدر» إلى النتائج المنقولة تلقائيًا عند إكمال بطولة للنادي – يُرجى تركها دون تغيير. في الزوجي يحتوي «الشريك» على الشريك بصيغة «الاسم الأول اسم العائلة»؛ ويمكن إكمال العمود لاحقًا وقراءة الملف مجددًا. في الزوجي يكفي الإدخال لدى أحد الشريكين. لا تزال الملفات التي لا تحتوي هذا العمود قابلة للقراءة.",
