"Für Saisons, die in den PDF-Dateien fehlen. Gelesen wird der Reiter „Bilanzen“ mit den Spalten Saison, Mannschaft, Name (Vorname Nachname), Anzahl Spiele, Anzahl Einzel, Einzel gewonnen/verloren und Doppel gewonnen/verloren; Salden und Summen berechnet die App selbst.": "للمواسم المفقودة في ملفات PDF. تُقرأ علامة التبويب «Bilanzen» بأعمدة الموسم، الفريق، الاسم (الاسم الأول اسم العائلة)، عدد المباريات، عدد الفرديات، الفرديات فوز/خسارة والزوجيات فوز/خسارة؛ ويحسب التطبيق الأرصدة والمجاميع بنفسه.",
"Jeder Upload ersetzt alle bisher manuell hochgeladenen Einträge.": "كل رفع يستبدل جميع الإدخالات المرفوعة يدويًا حتى الآن.",
"Stehen Saison, Mannschaft und Person zugleich in einer PDF, gilt der Wert aus der Excel-Datei.": "إذا ورد الموسم والفريق والشخص في ملف PDF أيضًا، تُعتمد القيمة من ملف Excel.",
