"Bilanzübersichten aus click-tt hochladen — mehrere Dateien auf einmal möglich. Die Saison wird aus dem Dateinamen gelesen (z. B. „Bilanzuebersicht_2025_26_Herren“), da sie im Dokument selbst nicht steht. Jede Datei ersetzt beim erneuten Hochladen nur ihren eigenen Stand, die übrigen Dateien der Saison bleiben erhalten.": "ارفع ملخصات الحصيلة من click-tt — يمكن رفع عدة ملفات معًا. يُقرأ الموسم من اسم الملف (مثل «Bilanzuebersicht_2025_26_Herren»)، لأنه غير مذكور في المستند نفسه. عند إعادة الرفع يستبدل كل ملف بياناته فقط؛ وتبقى ملفات الموسم الأخرى محفوظة.",
