"Jede Runde wird neu ausgelost: Wer gleich viele Siege hat, spielt gegeneinander. So trifft man mit fortschreitendem Turnier immer wahrscheinlicher auf ähnlich starke Gegner – unabhängig von Alter, Geschlecht und Spielstärke. Teilnehmen können auch Spieler anderer Vereine; sie werden unten als Gäste erfasst.": "تُجرى قرعة جديدة في كل جولة: من لديهم العدد نفسه من الانتصارات يلعبون معًا. وهكذا يزداد احتمال مواجهة خصوم بالمستوى نفسه مع تقدم البطولة – بغض النظر عن العمر والجنس ومستوى اللعب. يمكن أيضًا مشاركة لاعبين من أندية أخرى؛ ويُسجلون أدناه كضيوف.",
