"KO-Phase verwerfen und zur Gruppenphase zurück? Die im KO eingetragenen Ergebnisse gehen verloren.": "إلغاء مرحلة خروج المغلوب والعودة إلى مرحلة المجموعات؟ ستضيع النتائج المدخلة في مرحلة خروج المغلوب.",
