"markierte Saison gilt überall als Standard. Tipp: Mit „🔗 Link“ den myTischtennis-Link einer Mannschaft einfügen – Liga, Gruppe und Mannschafts-ID werden daraus übernommen.": "هو الافتراضي في كل مكان. نصيحة: استخدم «🔗 رابط» للصق رابط myTischtennis لفريق – يُؤخذ منه الدوري والمجموعة ومعرّف الفريق.",
"Die Saisons sind noch nicht gespeichert (es gilt die Vorbelegung). Bitte einmal unten auf „Saisons & Mannschaften speichern“ tippen – erst dann kann der Server die Tabellen abrufen.": "لم تُحفظ المواسم بعد (تسري القيم الافتراضية). يُرجى الضغط مرة على «حفظ المواسم والفرق» في الأسفل – عندها فقط يستطيع الخادم جلب الجداول.",
