"Konnte nicht speichern: ": "تعذّر الحفظ: ",
"Wer hier eingetragen ist, darf Daten ändern (Admin). Mit „Verwaltung“ erhält die Person zusätzlich Zugang zu diesem Bereich (Super-Admin). Welche Ansicht jemand sieht, regeln weiterhin die Funktionen im Profil. Änderungen wirken beim nächsten Start der App der betroffenen Person.": "من يُدرج هنا يحق له تغيير البيانات (مشرف). ومع «الإدارة» يحصل الشخص أيضًا على وصول إلى هذا القسم (مشرف رئيسي). أما العرض الذي يراه الشخص فتحدده الأدوار في الملف الشخصي. تسري التغييرات عند التشغيل التالي للتطبيق لدى الشخص المعني.",
"Die Liste ist noch nicht in der Datenbank gespeichert – angezeigt wird die bisherige Vorbelegung. Bitte einmal": "القائمة لم تُحفظ بعد في قاعدة البيانات – تُعرض القيم الافتراضية السابقة. يُرجى أولًا",
"; erst danach die neuen Firestore- und Storage-Regeln veröffentlichen.": "؛ وبعدها فقط نشر قواعد Firestore وStorage الجديدة.",
"· Betreiber der App (fest hinterlegt)": "· مشغّل التطبيق (ثابت)",
