"Erstellt eine vollständige Sicherung aller Vereinsdaten (Personen, Anwesenheit, Einsätze, Spielpläne, Einstellungen, Fotos, Beobachtungen, Turniere, Nachrichten …) als Datei. Bitte vor jedem Schritt der Umstellung auf getrennte Vereinsbereiche ausführen und die Datei außerhalb der App aufbewahren (z. B. in iCloud Drive oder auf dem PC). Am besten am Computer oder iPad im WLAN ausführen – die Datei kann wegen der Fotos groß werden.": "ينشئ نسخة احتياطية كاملة لكل بيانات النادي (الأشخاص، الحضور، المشاركات، جداول المباريات، الإعدادات، الصور، الملاحظات، البطولات، الرسائل …) كملف. يُرجى تنفيذها قبل كل خطوة من التحويل إلى أقسام منفصلة للأندية وحفظ الملف خارج التطبيق (مثل iCloud Drive أو على الحاسوب). الأفضل التنفيذ على حاسوب أو iPad عبر الشبكة اللاسلكية – قد يكون الملف كبيرًا بسبب الصور.",
