"Legt den Vereinsbereich mit Admin-Liste, Zugangsliste und Grunddaten an. Für den ersten Admin wird – falls nötig – ein Login-Konto erstellt und eine E-Mail zum Setzen des Passworts verschickt. Alles Weitere pflegt der Verein selbst.": "ينشئ قسم النادي مع قائمة المشرفين وقائمة الوصول والبيانات الأساسية. يُنشأ للمشرف الأول حساب دخول عند الحاجة ويُرسل بريد إلكتروني لتعيين كلمة المرور. ويتولى النادي بنفسه كل ما عدا ذلك.",
