"✅ Gespeichert. Die Adressen zusätzlich bei Netlify (Domains) eintragen.": "✅ تم الحفظ. أضف العناوين أيضًا في Netlify (النطاقات).",
"🌐 Adressen der Vereine": "🌐 عناوين الأندية",
"Mit einer Basis-Domain erhält jeder Verein automatisch die Adresse": "مع نطاق أساسي يحصل كل نادٍ تلقائيًا على العنوان",
". Zusätzlich kann je Verein eine eigene Domain eingetragen werden. Die Adresse bestimmt Anmeldeseite, Logo und Startbildschirm-Symbol. Jede Adresse muss außerdem bei Netlify als Domain eingetragen sein.": ". ويمكن إضافة نطاق خاص لكل نادٍ. يحدد العنوان صفحة الدخول والشعار وأيقونة الشاشة الرئيسية. ويجب أيضًا إضافة كل عنوان كنطاق في Netlify.",
"Basis-Domain": "النطاق الأساسي",
"z. B. vereinsapp.de": "مثل vereinsapp.de",
