"Alle Daten jetzt in den Vereinsbereich kopieren?\n\nDie bisherigen Daten bleiben unverändert und in Betrieb. Ein vorhandener Vereinsbereich wird exakt an den aktuellen Stand angeglichen.": "نسخ كل البيانات الآن إلى قسم النادي؟\n\nتبقى البيانات الحالية دون تغيير وقيد الاستخدام. وسيُطابَق قسم النادي الموجود تمامًا مع الحالة الحالية.",
" – Sind die neuen Firestore-Regeln veröffentlicht?": " – هل نُشرت قواعد Firestore الجديدة؟",
"Bitte zuerst eine aktuelle Sicherung erstellen (Abschnitt „💾 Datensicherung“, höchstens 3 Stunden alt).": "يُرجى إنشاء نسخة احتياطية حديثة أولًا (قسم «💾 النسخ الاحتياطي»، بعمر 3 ساعات كحد أقصى).",
"Jetzt auf den Vereinsbereich umschalten?\n\n1. Die App geht für alle kurz in den Wartungsmodus.\n2. Die Kopie wird ein letztes Mal erneuert und geprüft.\n3. Nur wenn alles identisch ist, arbeiten App und Server-Funktionen ab sofort mit vereine/": "التبديل الآن إلى قسم النادي؟\n\n1. يدخل التطبيق لفترة قصيرة في وضع الصيانة للجميع.\n2. تُحدَّث النسخة وتُفحص مرة أخيرة.\n3. فقط إذا تطابق كل شيء يعمل التطبيق ووظائف الخادم من الآن مع vereine/",
".\n\nBei Abweichungen bleibt alles beim Alten.": ".\n\nعند وجود اختلافات يبقى كل شيء كما هو.",
"Wartungsmodus ein …": "تشغيل وضع الصيانة …",
"Umschaltung abgebrochen: Abweichungen bei der Kopie": "أُلغي التبديل: اختلافات في النسخة",
"Fehler: Abweichungen bei der Abschlusskopie – Umschaltung abgebrochen, es bleibt bei der bisherigen Ablage.": "خطأ: اختلافات في النسخة النهائية – أُلغي التبديل، ويبقى التخزين السابق مستخدمًا.",
"✅ Umgeschaltet. Die App wird neu geladen …": "✅ تم التبديل. يُعاد تحميل التطبيق …",
"Umschaltung abgebrochen: ": "أُلغي التبديل: ",
" – Umschaltung abgebrochen, es bleibt bei der bisherigen Ablage.": " – أُلغي التبديل، ويبقى التخزين السابق مستخدمًا.",
"Zurück auf die bisherige Ablage schalten?\n\nDie Daten aus dem Vereinsbereich (inkl. aller Änderungen seit der Umschaltung) werden zuvor in die bisherige Ablage zurückkopiert und geprüft.": "العودة إلى التخزين السابق؟\n\nتُنسخ بيانات قسم النادي (بما فيها كل التغييرات منذ التبديل) أولًا إلى التخزين السابق وتُفحص.",
