"An diesen Tagen findet kein reguläres Training statt; Sondertrainings gelten zusätzlich (auch in den Ferien). Bereits erfasste Anwesenheiten bleiben erhalten. Trainingstage werden ab 2026 bis Ende {0} gebildet.": "لا يجري تدريب منتظم في هذه الأيام؛ وتسري التدريبات الخاصة إضافةً (حتى في العطل). يبقى الحضور المسجل محفوظًا. تُكوَّن أيام التدريب من 2026 حتى نهاية {0}.",
