"Die Beteiligung ergibt sich automatisch aus dem Trainingszeitraum in der Teilnahme-Auswertung. Jeder Spieler erhält genau eine Urkunde: die höchste erreichte Stufe ({0}). Hier das Datum der Vergabe eintragen; „📄 PDF“ erzeugt die Urkunde.": "تُحسب المشاركة تلقائيًا من فترة التدريب في تقييم الحضور. يحصل كل لاعب على شهادة واحدة بالضبط: أعلى مستوى بلغه ({0}). أدخل هنا تاريخ المنح؛ «📄 PDF» ينشئ الشهادة.",
