"Infos für die Aktiven (z. B. Hinweise in der Halle). Titel und Detailtext verfassen und optional Fotos hochladen. Fotos werden automatisch verkleinert (max. {0} px). Das Datum ist mit dem heutigen Tag vorbelegt und kann geändert werden. Mit 📌 lassen sich Infos oben fixieren; alle übrigen erscheinen nach Datum sortiert (neueste zuerst).": "معلومات للاعبين النشطين (مثل تنبيهات في الصالة). اكتب عنوانًا ونصًا تفصيليًا وارفع صورًا اختياريًا. تُصغَّر الصور تلقائيًا ({0} px كحد أقصى). يُملأ التاريخ مسبقًا بتاريخ اليوم ويمكن تغييره. بـ 📌 يمكن تثبيت المعلومات في الأعلى؛ وتُرتَّب البقية حسب التاريخ (الأحدث أولًا).",
"Trainingszeiten je Gruppe erfassen. Pro Zeit können bis zu drei Trainer zugeordnet werden (auch keiner – dann bleibt der Trainerbereich leer). Die Gruppe kann aus der Liste gewählt oder frei eingegeben werden. Trainerfotos werden automatisch verkleinert (max. {0} px).": "سجّل مواعيد التدريب لكل مجموعة. يمكن تعيين حتى ثلاثة مدربين لكل موعد (أو لا أحد – عندها تبقى منطقة المدربين فارغة). يمكن اختيار المجموعة من القائمة أو إدخالها بحرية. تُصغَّر صور المدربين تلقائيًا ({0} px كحد أقصى).",
"Fotos werden je Saison gespeichert und im Spielbetrieb angezeigt. Große Bilder werden automatisch auf max. {0} px verkleinert und komprimiert.": "تُحفظ الصور لكل موسم وتُعرض في الدوري. تُصغَّر الصور الكبيرة تلقائيًا إلى {0} px كحد أقصى وتُضغط.",
