"Für dich ist keine Abrechnung freigeschaltet. Die Freigabe erfolgt in der Verwaltung (Person › Training und Vereinsbeitritt › „Abrechnung“).": "المحاسبة غير مفعّلة لك. يتم التفعيل في الإدارة (الشخص › التدريب والانضمام للنادي › «المحاسبة»).",
