"Lade je Stufe das Urkundenmuster hoch (A4 hochkant). Beim Erzeugen setzt die App Vorname, Name, Ort und Datum, das Logo der App, den Rahmen in der Vereinsfarbe sowie unten den Text mit Zeitraum, Anzahl der Trainings, Anwesenheitsquote und Stufe. Position von Ort/Datum, Logo und Rahmen wie bei den Übungs-Urkunden (Einstellungen dort).": "ارفع لكل مستوى نموذج الشهادة (A4 عمودي). عند الإنشاء يضع التطبيق الاسم الأول واسم العائلة والمكان والتاريخ وشعار التطبيق والإطار بلون النادي، وفي الأسفل النص مع الفترة وعدد التدريبات ونسبة الحضور والمستوى. موضع المكان/التاريخ والشعار والإطار كما في شهادات التمارين (الإعدادات هناك).",
"Erzeugt werden die Urkunden in der Verwaltung › Personen › Personenverwaltung › Person › „Urkunden (Trainingsbeteiligung)“.": "تُنشأ الشهادات في الإدارة › الأشخاص › إدارة الأشخاص › الشخص › «الشهادات (المشاركة في التدريب)».",
